-- samples/lub_prelude.lua が lub table に過不足なく持つかを確かめる。
local M = {}

local function check(path, kind)
	local v = lub
	for seg in string.gmatch(path, "[^.]+") do
		v = v and v[seg]
	end
	assert(v ~= nil, "lub." .. path .. " is missing from the prelude")
	if kind == "function" then
		assert(type(v) == "function", "lub." .. path .. " must be a function")
	end
end

function M.on_init()
	lub.config({ backend = os.getenv("LUB_BACKEND") or "sdlgpu" })
end

